content.content:
    ld -nostdlib --no-undefined --orphan-handling=error -T firmware/app.ld \
        -o "$out/app.elf" $objs
    # The raw image is the code, then the initial data, which app.ld loads
    # right after it. This objcopy takes one section at a time, and ld's
    # own binary output gets data addresses wrong, so the two are joined.
    objcopy -O binary -j .text "$out/app.elf" "$obj/text.bin"
    objcopy -O binary -j .data "$out/app.elf" "$obj/data.bin"
    cat "$obj/text.bin" "$obj/data.bin" > "$out/app.bin"
    rm "$obj/text.bin" "$obj/data.bin"
    set +x
    # fwtest doesn't run the two-register load or store that moves its
    # address first (`{rA, rB} = [-rC]` and its kin), which clang makes of
    # some copies (M5; SR-7): an image holding one faults there.
    if objdump -d "$out/app.elf" | grep -E '\} = \[-r|\[-r[0-9]+\] = \{'; then
        echo "FAIL: app.elf has an instruction fwtest doesn't run (SR-7)" >&2; exit 1
    fi
    write_size "$out/app.elf" > "$out/app.size"
    cat "$out/app.size"
    image=$(awk '$1 == "image" { print $2 }' "$out/app.size")
    if [ "$(wc -c < "$out/app.bin")" -ne "$image" ]; then
        echo "FAIL: app.bin is not the $image bytes app.ld lays out" >&2; exit 1
    fi
    # No output may contain the absolute source path.
    for f in $(find "$out" -type f | LC_ALL=C sort); do
        if grep -q -F "$src" "$f"; then
            echo "FAIL: $f contains the source path $src" >&2; exit 1
        c = (c + a) % 255u;
    }
    return c << 8 | a;
}

/* --- Notes ------------------------------------------------------------ */

/* A word at a time: clang makes these copies with a two-register load
 * that moves its address down first, which fwtest doesn't run (it faults:
 * SR-7); tools/build.sh fails an image that holds one. */
static void copy_words(s32 *dst, const volatile s32 *src, u32 n)
{
    while (n--)
        *dst++ = *src++;
}

/* Starts note on voice n from the current patch. A free voice starts from
 * silence at phase 0; one still sounding (the same note again, or mono)
 * keeps its phases and starts its attacks from where its envelopes are,
 * so neither clicks. */
static void voice_start(u32 n, int note, u32 velocity)
{
    struct fm_voice *v = &voice[n];
    struct control *c = &ctl[n];
    const struct patch *p = &patches[patch_now];
    u32 i, fresh = v->state != VOICE_ON, carriers = 0;
    /* Velocity: up to 8 octaves (48 dB) less at velocity 0, for a
     * sensitivity of 7, in proportion below (DESIGN-NOTES.md, M5). */
    s32 soft = (s32)(127u - velocity) * (8 * 65536 / 7) / 127;

    c->patch = p;
    c->note = note;
    c->held = 1;
    c->next = -1;
    c->age = started++;
    c->pitch = (note + p->transpose) * SEMITONE;
    c->glide_left = 0;
    c->pitch_stage = 0;
    c->pitch_level = p->pitch_level[0];
    v->algorithm = algorithm_now;
    for (i = 0; i < FM_OPS; i++) {
        struct fm_op *o = &v->op[i];
        if (fresh) {
            o->phase = 0;
            o->gain = 0;
            o->y1 = o->y2 = 0;
            o->lin = 0;
        } else if (o->stage != ENV_ATTACK) {
            o->lin = o->stage == ENV_OFF ? 0 : fm_exp2_neg(o->att);
        }
        o->fixed = p->op[i].fixed;
        o->freq = p->op[i].freq;
        o->detune = p->op[i].detune;
        o->fixed_att = p->op[i].level_att + soft * p->op[i].velocity;
        copy_words(o->step, p->op[i].step, 4);
        copy_words(o->target, p->op[i].target, 3);
        o->stage = p->op[i].off ? ENV_OFF : ENV_ATTACK;
        carriers += !p->op[i].off && fm_algorithms[algorithm_now].dest[i] == FM_TO_OUT;
    }
    v->out_att = fm_carrier_att(carriers);
    if (fresh) {
        v->fb_now = 0;
        sounding++;
    }
    v->fade = 0;
    v->fade_done = 0;
- **Sizes**: code 15.7 KB (6.6 KB more than before the engine, the test
  patches' 1 KB among it), static RAM 142.0 KB (18.0 KB more: the voices
  7.9 KB, the mixes and scratch 4.1 KB, the sine and exp2 tables 5.1 KB,
  the parsed patches 3.7 KB, core 0's notes on the voices 0.8 KB, core
  1's stack 1 KiB; M4's instrument's 4.5 KB gone), stack 388 bytes.
  Startup 1 032 624 instructions.

#### Workaround: SR-7
fwtest doesn't run the two-register load that moves its address down
first (`{r3, r0} = [-r4]`), which clang made of seven consecutive word
copies in `voice_start()` (fm_play.c), with or without `-mcpu=r3
-mfprev1`; the image faulted there. Until fwtest runs it (SR-7,
docs/SPEC-REQUESTS.md), those copies go through `copy_words()`, a word at
a time from a volatile pointer, and tools/build.sh fails any image whose
disassembly holds the form, so a new one can't reach fwtest unnoticed.
Both go once SR-7 is answered.

