                env += d;
                if (env >= ENV_FULL) {
                    env = ENV_FULL;
                    d = 0;
                    tone_state = TONE_HOLD;
                } else if (env <= 0) {
                    env = 0;
                    d = 0;
                    tone_state = TONE_OFF;
                    sb_audio.engine[SYNTH_LAST_OFF] = sb_audio.blocks;
                }
            }
            s = s > AUDIO_FULL ? AUDIO_FULL : s < -AUDIO_FULL ? -AUDIO_FULL : s;
            w[0] = s;
            w[1] = s;
        }
        tone_env = env;
    }
