void fm_init(void)
{
    u32 n, saved;

    fm_tables();
    for (n = 0; n < FM_PATCHES; n++)
        patch_parse(&patches[n], fm_patches[n]);
    for (n = 0; n < 27; n++)
        key_note[n] = -1;
    for (n = 0; n < FM_VOICES; n++)
