        s32 detune, level_att, velocity;
        s32 step[4], target[3];
    } op[FM_OPS];
};

/* What core 0 keeps for each voice. */
struct control {
    int note;          /* the note sounding */
    u32 held;          /* its key is down */
    u32 age;           /* when it began, in notes started */
