    s32 glide_to, glide_step;
    u32 glide_left;    /* blocks */
    u32 pitch_stage;   /* 0 toward P1, 1 toward P2 (then held), 2 released */
    s32 pitch_level;   /* the pitch envelope, 2^-16 of a level */
