    if (b[FMP_ALGORITHM] < 1 || b[FMP_ALGORITHM] > FM_ALGORITHMS || b[FMP_FEEDBACK] > 7
        || b[FMP_FLAGS] > 1 || b[FMP_GLIDE] > 127)
