        if (b[FMP_PITCH_RATE + i] > 127)
            return 0;
    for (i = 0; i < 4; i++)
        if (signed8(b[FMP_PITCH_LEVEL + i]) < -127)
            return 0;
    for (i = 29; i < 32; i++)
        if (b[i])
