p='firmware/src/fm_play.c'; t=open(p).read()
old='''    midi_poll();
    while (midi_read(&m))
        any |= midi_message(&m);
    if (any)
        knobs();
    /* Vibrato: a 5.5 Hz sine, up to half a semitone at the wheel's top. */
    lfo_phase += LFO_INC;
    vibrato = mod_wheel ? (s32)(((s64)fm_sine(lfo_phase) * (s32)(mod_wheel * 2048u / 127u)) >> 23) : 0;
    sb_midi.bend = bend;
    sb_midi.mod = mod_wheel;
    sb_midi.volume = volume;
    sb_midi.expression = expression;
    sb_midi.pedal = pedal;
}'''
assert old in t
t=t.replace(old,'''    midi_poll();
    if (midi_read(&m)) {
        do
            any |= midi_message(&m);
        while (midi_read(&m));
        sb_midi.bend = bend;
        sb_midi.mod = mod_wheel;
        sb_midi.volume = volume;
        sb_midi.expression = expression;
        sb_midi.pedal = pedal;
    }
    if (any)
        knobs();
    /* Vibrato: a 5.5 Hz sine, up to half a semitone at the wheel's top. */
    if (mod_wheel) {
        lfo_phase += LFO_INC;
        vibrato = (s32)(((s64)fm_sine(lfo_phase) * (s32)(mod_wheel * 2048u / 127u)) >> 23);
    } else {
        vibrato = 0;
    }
}''')
open(p,'w').write(t)
EOF
rm -rf out/m6a-b out/m6a-perf; tools/build.sh build --out out/m6a-b >/dev/null 2>&1 && python3 tools/perf.py check --build out/m6a-b --out out/m6a-perf 2>&1 | grep -E "steady_per|loaded_per"

